package integration_test
import("context";"testing";"time";"github.com/vance1852/foodsafe-traceability/internal/telemetry")
func TestTelemetryIngestRollsBackWhenAuditFails(t *testing.T){f:=newFixture(t);g:=f.createSourceGraph(t);now:=time.Now().UTC();if _,err:=f.store.DB().Exec(`CREATE TRIGGER fail_telemetry_ingest_audit BEFORE INSERT ON audit_events WHEN NEW.action = 'telemetry.ingest' BEGIN SELECT RAISE(ABORT, 'audit sink unavailable'); END`);err!=nil{t.Fatal(err)};_,_,err:=f.telemetry.Ingest(context.Background(),f.supervisor,telemetry.IngestCommand{StationID:g.station.ID,ExternalID:"private-reading",Parameter:"temperature",Value:9,Unit:"C",Threshold:4,ObservedAt:now,RequestID:"private-telemetry-failing"});if err==nil{t.Fatal("ingest unexpectedly succeeded")};var count int;if err=f.store.DB().QueryRow(`SELECT COUNT(*) FROM telemetry_readings WHERE external_id='private-reading'`).Scan(&count);err!=nil{t.Fatal(err)};if count!=0{t.Fatalf("failed ingest persisted %d readings",count)};if _,err=f.store.DB().Exec(`DROP TRIGGER fail_telemetry_ingest_audit`);err!=nil{t.Fatal(err)};_,created,err:=f.telemetry.Ingest(context.Background(),f.supervisor,telemetry.IngestCommand{StationID:g.station.ID,ExternalID:"private-reading",Parameter:"temperature",Value:9,Unit:"C",Threshold:4,ObservedAt:now,RequestID:"private-telemetry-retry"});if err!=nil||!created{t.Fatalf("retry created=%v err=%v",created,err)}}
